begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(12);
select set_config('app.tenant_id','96000000-0000-4000-8000-000000000001',true);
insert into orchestration.artifact(id,tenant_id,artifact_type,sha256,bucket_class,storage_bucket,object_path,media_type,size_bytes,storage_state,available_at,verification_contract_version)
select ('96000000-0000-4000-8000-0000000000'||n)::uuid,util.current_tenant_id(),'source_query_response',repeat(right(n,1),64),'source_captures','ai-engineer-cloud-bucket',util.current_tenant_id()::text||'/'||right(n,1)||right(n,1)||'/'||repeat(right(n,1),64),'application/json',10,'available',clock_timestamp(),'verification.v1' from unnest(array['10','11','12']) n;
insert into orchestration.verification_artifact_metadata(tenant_id,artifact_id,producer_activity_id,producer_version,encryption_class,retention_class,data_classification) values(util.current_tenant_id(),'96000000-0000-4000-8000-000000000010','root-test','v1','managed','audit','internal');
insert into orchestration.verification_artifact_metadata(tenant_id,artifact_id,producer_activity_id,producer_version,encryption_class,retention_class,data_classification,parent_artifact_ids,transformation_signature)
select util.current_tenant_id(),('96000000-0000-4000-8000-0000000000'||n)::uuid,'selection-test','v1','managed','audit','internal',array['96000000-0000-4000-8000-000000000010'::uuid],repeat('a',64) from unnest(array['11','12']) n;
insert into orchestration.artifact_lineage(tenant_id,from_artifact_id,to_artifact_id,relation_kind,activity_id,activity_version,transformation_signature) select util.current_tenant_id(),('96000000-0000-4000-8000-0000000000'||n)::uuid,'96000000-0000-4000-8000-000000000010','generated','selection-test','v1',repeat('a',64) from unnest(array['11','12']) n;
insert into evidence.source_query(id,tenant_id,provider_code,query_text,purpose,parameters) select '96000000-0000-4000-8000-000000000020',util.current_tenant_id(),code,'recovery','test','{}' from evidence.search_provider order by code limit 1;
insert into evidence.source_provider_attempt(id,tenant_id,source_query_id,provider_code,origin,idempotency_key,request_sha256,request_artifact_id,state)
select '96000000-0000-4000-8000-000000000030',util.current_tenant_id(),id,provider_code,'managed','started',repeat('a',64),'96000000-0000-4000-8000-000000000010','started' from evidence.source_query where id='96000000-0000-4000-8000-000000000020';
select throws_ok($q$update evidence.source_provider_attempt set original_dispatch_token='96000000-0000-4000-8000-000000000090',original_dispatch_fencing_token=null where id='96000000-0000-4000-8000-000000000030'$q$,'23514',null,'NULL original fence cannot bypass identity check');
select throws_ok($q$update evidence.source_provider_attempt set original_dispatch_token=null,original_dispatch_fencing_token=1 where id='96000000-0000-4000-8000-000000000030'$q$,'23514',null,'NULL token cannot accompany a fence');
select lives_ok($q$update evidence.source_provider_attempt set original_dispatch_token='96000000-0000-4000-8000-000000000090',original_dispatch_fencing_token=1 where id='96000000-0000-4000-8000-000000000030'$q$,'original dispatch pair is recorded');
select throws_ok($q$update evidence.source_provider_attempt set original_dispatch_fencing_token=2 where id='96000000-0000-4000-8000-000000000030'$q$,'23001',null,'original dispatch stays immutable');
insert into evidence.source_provider_attempt(id,tenant_id,source_query_id,provider_code,origin,idempotency_key,request_sha256,request_artifact_id,external_receipt_artifact_id,state,completion_sha256,completed_at,attempt_ordinal)
select '96000000-0000-4000-8000-000000000031',util.current_tenant_id(),id,provider_code,'imported','complete',repeat('a',64),'96000000-0000-4000-8000-000000000010','96000000-0000-4000-8000-000000000010','succeeded',repeat('b',64),clock_timestamp()+interval '1 second',1 from evidence.source_query where id='96000000-0000-4000-8000-000000000020';
insert into evidence.provider_result(tenant_id,query_id,rank,source_provider_attempt_id,disposition) values(util.current_tenant_id(),'96000000-0000-4000-8000-000000000020',1,'96000000-0000-4000-8000-000000000031','unreviewed');
select lives_ok($q$insert into evidence.provider_result(tenant_id,query_id,rank,source_provider_attempt_id,disposition) values(util.current_tenant_id(),'96000000-0000-4000-8000-000000000020',1,'96000000-0000-4000-8000-000000000030','unreviewed')$q$,'typed retries can reuse rank on original query');
insert into evidence.provider_result(tenant_id,query_id,rank) values(util.current_tenant_id(),'96000000-0000-4000-8000-000000000020',2);
select throws_ok($q$insert into evidence.provider_result(tenant_id,query_id,rank) values(util.current_tenant_id(),'96000000-0000-4000-8000-000000000020',2)$q$,'23505',null,'legacy query/rank dedup remains enforced');
select throws_ok($q$insert into evidence.source_selection_revision(tenant_id,attempt_id,revision,idempotency_key,request_sha256,selection_artifact_id) values(util.current_tenant_id(),'96000000-0000-4000-8000-000000000031',1,'orphan',repeat('c',64),'96000000-0000-4000-8000-000000000011'); set constraints evidence.source_selection_revision_nonempty immediate$q$,'23514',null,'empty revision cannot commit');
insert into evidence.source_selection_revision(tenant_id,attempt_id,revision,idempotency_key,request_sha256,selection_artifact_id) values(util.current_tenant_id(),'96000000-0000-4000-8000-000000000031',1,'select',repeat('c',64),'96000000-0000-4000-8000-000000000011');
select throws_ok($q$insert into evidence.source_result_selection(tenant_id,attempt_id,revision,rank,disposition,reason,idempotency_key,selection_artifact_id) values(util.current_tenant_id(),'96000000-0000-4000-8000-000000000031',1,1,'selected','reason','wrong','96000000-0000-4000-8000-000000000011')$q$,'23503',null,'selection key must match exact revision');
select throws_ok($q$insert into evidence.source_result_selection(tenant_id,attempt_id,revision,rank,disposition,reason,idempotency_key,selection_artifact_id) values(util.current_tenant_id(),'96000000-0000-4000-8000-000000000031',1,1,'selected','reason','select','96000000-0000-4000-8000-000000000012')$q$,'23503',null,'selection artifact must match exact revision');
select lives_ok($q$insert into evidence.source_result_selection(tenant_id,attempt_id,revision,rank,disposition,reason,idempotency_key,selection_artifact_id) values(util.current_tenant_id(),'96000000-0000-4000-8000-000000000031',1,1,'selected','reason','select','96000000-0000-4000-8000-000000000011');set constraints all immediate$q$,'admitted parent-bound revision commits');
select throws_ok($q$update evidence.source_selection_revision set idempotency_key='changed' where tenant_id=util.current_tenant_id()$q$,'23001',null,'revision receipt stays immutable');
select throws_ok($q$update evidence.source_result_selection set disposition='omitted' where tenant_id=util.current_tenant_id()$q$,'23001',null,'decision stays immutable');
select * from finish();
rollback;
